/* Project-wide creative direction. No media is regenerated by saving a style. */
const STORY_STYLES=[
 {id:'healing',name:'治愈手绘',tone:'温暖治愈，以陪伴、信任与成长为主线。保留故事的生活气息，冲突服务于人物关系，情感克制而真诚。',visual:'米黄纸张质感，精细深灰手绘线条，柔和淡彩二维画面。自然暖光，低饱和青绿与米金色，环境细腻，光影柔和。',rhythm:'舒缓但不拖沓，重视眼神、手部动作与自然停顿；转场连贯，给环境与情绪留出呼吸。',avoid:'避免高饱和霓虹、写实3D塑料感、夸张搞笑表情、血腥惊吓及解释性旁白。'},
 {id:'daily',name:'温馨日常',tone:'聚焦生活细节、亲密关系和细小的成长，轻松自然，温暖有趣。',visual:'清新二维插画，柔和自然光，明亮低饱和配色，富有生活气息的场景细节。',rhythm:'从容自然，以人物互动推动叙事，适度留白。',avoid:'避免强行煽情、过密反转和过度戏剧化。'},
 {id:'fantasy',name:'唯美奇幻',tone:'浪漫、神秘而富有探索感，突出世界的奇妙与人物的情感羁绊。',visual:'细腻二维绘画，通透色彩，层次丰富的自然景观，克制的魔法光效。',rhythm:'情绪铺陈与奇观揭示交替，关键时刻放缓。',avoid:'避免杂乱特效、廉价光污染和无因果的奇观堆砌。'},
 {id:'adventure',name:'热血冒险',tone:'明确的目标与挑战，以勇气、协作和成长推动故事。',visual:'富有动势的二维动画画面，清晰轮廓与光影对比，动作空间易于辨认。',rhythm:'紧凑有张弛，行动因果清晰，重大情绪节点保留停顿。',avoid:'避免无意义打斗、频繁跳切和动作位置混乱。'},
 {id:'mystery',name:'悬疑氛围',tone:'围绕线索与人物动机逐步揭示真相，控制信息量，保持可信的因果。',visual:'克制的二维电影感画面，冷暖对比，局部照明和有层次的暗部。',rhythm:'铺垫、发现与反转交替，使用视线和场景细节制造悬念。',avoid:'避免血腥堆砌、突兀惊吓和为反转破坏人物逻辑。'}
];
function projectStyle(){return state.storyStyle||(state.title==='雨后的小店'?STORY_STYLES[0]:{id:'custom',name:'自定义风格',tone:'尊重原作的剧情基调与人物关系。',visual:'保持同一剧集画面风格一致。',rhythm:'动作与转场自然连贯。',avoid:''})}
function styleDirection(s=projectStyle()){return `全剧风格：${s.name}\n剧情基调：${s.tone}\n画面风格：${s.visual}\n叙事节奏：${s.rhythm}\n避免事项：${s.avoid||'无额外要求'}\n仅调整表现方式，不擅自改写剧情事实、原始对白或已批准的人物形象。若旧提示词与上述风格冲突，采用本次全剧风格。`}
function styledPrompt(prompt,s=projectStyle()){return `${prompt||''}\n\n【本次全剧风格要求】\n${styleDirection(s)}`}
function styleCard(compact=false){const s=projectStyle();return `<section class="story-style-card ${compact?'compact':''}" id="projectStyleCard"><div><div class="eyebrow">STORY DIRECTION · 全剧统一</div><h3>全剧风格 <span>${esc(s.name)}</span></h3><p>${esc(compact?s.tone:s.visual)}</p>${compact?'':'<small>剧情基调 · 画面风格 · 叙事节奏 · 自定义要求</small>'}</div><button id="editProjectStyle">选择 / 自定义风格 ↗</button></section>`}
function mountStyleCard(){if(!['source','episodes'].includes(page))return;$('#projectStyleCard')?.remove();if(page==='source')$('.page-heading').insertAdjacentHTML('afterend',styleCard());else $('.tabs').insertAdjacentHTML('beforebegin',styleCard(true));$('#editProjectStyle').onclick=styleDialog}
function styleDialog(){let draft=structuredClone(projectStyle());openModal(`${modalTop('定义整部剧的风格')}<p class="muted">先选一个方向，再按你的故事调整。整个项目的后续分镜、形象与关键帧共用这份设定。</p><div class="style-presets" role="group" aria-label="风格预设">${[...STORY_STYLES,{id:'custom',name:'＋ 自定义风格'}].map(s=>`<button data-style-preset="${s.id}" aria-pressed="${draft.id===s.id}">${esc(s.name)}</button>`).join('')}</div><label class="field">风格名称<input id="styleName" maxlength="80"></label><div class="detail-grid"><div><label class="field">剧情基调<textarea id="styleTone" maxlength="3000" placeholder="例如：治愈、陪伴、慢慢建立信任…"></textarea></label><label class="field">叙事节奏<textarea id="styleRhythm" maxlength="3000" placeholder="例如：舒缓、细腻，给情绪留出停顿…"></textarea></label></div><div><label class="field">画面风格<textarea id="styleVisual" maxlength="3000" placeholder="描述画风、材质、色彩、光线…"></textarea></label><label class="field">避免事项（可选）<textarea id="styleAvoid" maxlength="3000" placeholder="例如：不使用3D质感、霓虹色…"></textarea></label></div></div><div class="notice">保存后应用于新发起的生成。已有镜头和素材不会自动重做；进行中的整集任务继续使用启动时的风格。声音仍沿用已确认音色。</div><div class="dialog-footer"><button data-close>取消</button><button class="primary" id="saveProjectStyle">保存全剧风格</button></div>`);
const fields={name:'styleName',tone:'styleTone',visual:'styleVisual',rhythm:'styleRhythm',avoid:'styleAvoid'};function fill(){for(const [key,id] of Object.entries(fields))$('#'+id).value=draft[key]||'';$$('[data-style-preset]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.stylePreset===draft.id)))}fill();$$('[data-style-preset]').forEach(b=>b.onclick=()=>{draft=structuredClone(STORY_STYLES.find(s=>s.id===b.dataset.stylePreset)||{id:'custom',name:'我的自定义风格',tone:'',visual:'',rhythm:'',avoid:''});fill()});for(const id of Object.values(fields))$('#'+id).oninput=()=>{draft.id='custom';$$('[data-style-preset]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.stylePreset==='custom')))};$('#saveProjectStyle').onclick=()=>{for(const [key,id] of Object.entries(fields))draft[key]=$('#'+id).value.trim();if(!draft.name||!draft.tone||!draft.visual||!draft.rhythm)return toast('请填写风格名称、剧情基调、画面风格与叙事节奏');state.storyStyle={...draft,updatedAt:new Date().toISOString()};save();$('#modal').close();mountStyleCard();toast('全剧风格已保存，后续生成将使用这份设定')}}
const renderBeforeStyle=render;render=function(){renderBeforeStyle();mountStyleCard()};
